export { anatomy, parts, type ToolbarPart } from "./toolbar.anatomy";
export { connect } from "./toolbar.connect";
export { getItemEls, getItemId, getItemValues, getRootEl, getRootId } from "./toolbar.dom";
export { machine } from "./toolbar.machine";
export type {
  ResolvedToolbarMachineProps,
  ToolbarApi,
  ToolbarItemProps,
  ToolbarMachineProps,
  ToolbarSchema,
  ToolbarSeparatorProps,
  ToolbarTitleProps,
} from "./toolbar.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type ToolbarPart = "root" | "group" | "separator" | "spacer" | "item" | "title";

export const anatomy: Anatomy<ToolbarPart> = createAnatomy("toolbar").parts(
  "root",
  "group",
  "separator",
  "spacer",
  "item",
  "title",
);

export const parts: Record<ToolbarPart, AnatomyPart> = anatomy.build();

import { ariaAttr, dataAttr } from "../../dom/attrs";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction } from "../../focus/roving-focus";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality, isTextEntryTarget } from "../../nav";
import type { Orientation } from "../../types";
import { parts } from "./toolbar.anatomy";
import { getItemId, getRootEl, getRootId } from "./toolbar.dom";
import type {
  ToolbarApi,
  ToolbarItemProps,
  ToolbarSchema,
  ToolbarSeparatorProps,
  ToolbarTitleProps,
} from "./toolbar.types";

export function connect<T extends PropTypes>(
  service: Service<ToolbarSchema>,
  normalize: NormalizeProps<T>,
): ToolbarApi<T> {
  const { context, prop, send, scope } = service;

  const orientation = prop("orientation");
  const focusedValue = context.get("focusedValue");
  // Read once, when focus lands, and held: the modality of `now` flips to
  // pointer after 300ms of mouse movement whether or not the focus moved.
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);
  // The single tab stop, settled by the machine against the real item list.
  const tabbableValue = context.get("tabbableValue");

  return {
    focusedValue,

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        role: "toolbar",
        dir: prop("dir"),
        // APG requires the name. A consumer who would rather point at a visible
        // heading spreads their own `aria-labelledby`, which wins the merge.
        "aria-label": prop("label"),
        // Only the vertical case is worth spelling out: horizontal is the
        // implicit value of `aria-orientation` on a toolbar.
        "aria-orientation": orientation === "vertical" ? "vertical" : undefined,
        "data-orientation": orientation,
        // One spatial zone on its own axis. The engine's default entry strategy
        // (`last`, geometric fallback) coincides with the keyboard memory below,
        // so the d-pad and Tab come back to the same control for free. No
        // `data-snav-wrap`: a spatial wrap at the edge would make the bar
        // impossible to *leave* with a d-pad.
        "data-snav": "container",
      }),

    getGroupProps: (): T["element"] =>
      normalize.element({
        ...parts.group.attrs,
        role: "group",
        "data-orientation": orientation,
      }),

    getSeparatorProps: (separatorProps: ToolbarSeparatorProps = {}): T["element"] => {
      // A rule between two groups runs across the bar, so its own orientation is
      // the perpendicular of the toolbar's — which is what makes the default the
      // right one and the prop a rarity.
      const own: Orientation =
        separatorProps.orientation ?? (orientation === "horizontal" ? "vertical" : "horizontal");

      return normalize.element({
        ...parts.separator.attrs,
        role: "separator",
        "aria-orientation": own === "vertical" ? "vertical" : undefined,
        "data-orientation": own,
      });
    },

    getSpacerProps: (): T["element"] =>
      normalize.element({
        ...parts.spacer.attrs,
        "aria-hidden": ariaAttr(true),
      }),

    getTitleProps: (titleProps: ToolbarTitleProps = {}): T["element"] =>
      normalize.element({
        ...parts.title.attrs,
        "data-size": titleProps.size ?? "inline",
      }),

    getItemProps: (itemProps: ToolbarItemProps & { value: string }): T["element"] => {
      const { value } = itemProps;
      const focused = focusedValue === value;

      return normalize.element({
        ...parts.item.attrs,
        id: getItemId(scope, value),
        // The value lives on the element because the DOM is where the item order
        // is read from — this is what keeps the machine out of a registry.
        "data-value": value,
        "data-orientation": orientation,
        // Tri-state, and the third state is the point. Until the first
        // `ITEMS.SYNC` the machine has read no items, and writing `-1` on every
        // one of them would take the whole bar out of the tab order of a
        // server-rendered page. Absent, the native focusables keep their natural
        // order until hydration settles the stop.
        tabIndex: tabbableValue === null ? undefined : value === tabbableValue ? 0 : -1,
        "data-focus-visible": dataAttr(focused && focusVisible),
        // On the focused item only: the bar has one focus, and an attribute
        // claiming otherwise on every control describes nothing.
        "data-focus-source": focused ? (focusSource ?? undefined) : undefined,
        // Memory only. A toolbar visits, it does not choose: the activation
        // belongs to the control that was clicked.
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "ITEM.CLICK", value });
        },
        onKeyDown(event) {
          // The cohabitation rule, in the order it has to be read.
          //
          // A composed control that claimed the key has already won, whatever
          // order the handlers were merged in — a menu trigger opening on Down
          // must not also move the focus sideways.
          if (event.defaultPrevented) return;
          // A modifier means an application shortcut, and Shift+arrow is the
          // range-extend gesture of the components that have ranges. Neither is
          // ever a toolbar move (the `getRovingKeyAction` convention).
          if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
          // A caret owns its arrows, Home and End. An item that *is* a text field
          // is unusual but legal, and the field wins.
          if (isTextEntryTarget(event.target)) return;

          // `bothAxes: false` always: the toolbar holds strictly to its own axis
          // so the perpendicular one stays free for the page to scroll, or for a
          // spinbutton inside the bar. That is the deliberate difference with the
          // radio mode of `toggle-group`. The RTL mirror lives in the shared key
          // map, once per composite, never in the intent keymap.
          const action = getRovingKeyAction(event.key, {
            orientation,
            dir: resolveDir(prop("dir"), getRootEl(scope)),
            bothAxes: false,
          });
          if (action === null) return;
          event.preventDefault();
          send({ type: "ITEM.NAVIGATE", action, value });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "ITEM.FOCUS", value });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "ITEM.BLUR" });
        },
      });
    },
  };
}

import { queryItems } from "../../collection/dom-collection";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "toolbar";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getItemId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "item", value);
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * The item order is the DOM order, read when it is needed rather than kept in a
 * registry the consumer would have to maintain. The container filter is what makes
 * a toolbar nested inside another one harmless: an item answers to the toolbar it
 * is closest to, and to no other.
 */
export function getItemEls(scope: Scope): HTMLElement[] {
  return queryItems(getRootEl(scope), '[data-part~="toolbar:item"]', '[data-part~="toolbar:root"]');
}

export function getItemValues(scope: Scope): string[] {
  return getItemEls(scope).map((item) => item.dataset.value ?? "");
}

export function getCurrentValue(scope: Scope): string | null {
  const current = getItemEls(scope).find(
    (item) => item.getAttribute("aria-current") === "page" && !item.hasAttribute("disabled"),
  );
  return current === undefined ? null : (current.dataset.value ?? "");
}

/**
 * The APG toolbar: a row of heterogeneous controls reduced to one tab stop by a
 * roving tabindex. `toggle-group` minus the selection — same collection read from
 * the DOM, same modality capture, same single-stop arithmetic — and the two
 * differences are the whole component.
 *
 * **A toolbar visits, it does not choose.** Single-selection `toggle-group` is a
 * radio group, where an arrow moves *and* selects; nothing here follows the
 * focus, because the controls own their own activation.
 *
 * **Leaves are items, composites are islands.** Only `[data-part~="toolbar:item"]`
 * takes part in the roving, so a `toggle-group`, a `tabs` list or a search field
 * dropped into the bar keeps its own tab stop and its own arrows — APG's "avoid
 * including controls whose operation requires the arrow keys" turned into a rule
 * the markup states rather than one the machine has to detect. The arrows step
 * over an island because it is not in the collection, and Tab reaches it in DOM
 * order.
 */

import { observeChildren } from "../../dom/observers";
import { getInitialIndex, getNextIndex } from "../../focus/roving-focus";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { focusElement, getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { isDev } from "../../utils/env";
import { warn } from "../../utils/invariant";
import { getCurrentValue, getItemEls, getItemValues, getRootEl } from "./toolbar.dom";
import type { ToolbarSchema } from "./toolbar.types";

export const machine: Machine<ToolbarSchema> = createMachine<ToolbarSchema>({
  props({ props }) {
    return {
      orientation: "horizontal",
      // APG leaves the wrap optional; `toggle-group` and `tabs` loop, so this one
      // does too. It is a keyboard politeness only — the d-pad deliberately gets
      // no `data-snav-wrap`, or the bar would be impossible to leave.
      loopFocus: true,
      ...props,
    };
  },

  context({ bindable }) {
    return {
      tabbableValue: bindable<string | null>(() => ({ defaultValue: null })),
      focusedValue: bindable<string | null>(() => ({ defaultValue: null })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackItems", "warnIfAnonymous"],

  watch({ scope, track, action }) {
    // The item list is a dependency like any other: an adapter that re-renders
    // settles the tab stop synchronously, and the observer below is left to cover
    // the mutations no render caused.
    //
    // The separator is spelled rather than typed. The raw byte in a source file
    // makes ripgrep call the module binary and skip it — every grep in the repo,
    // and every review built on one, goes blind to it (the lesson `toggle-group`
    // paid for). U+0000 stays the character because it is the one an attribute
    // value cannot carry, so two different item lists can never key the same.
    track(
      () => [getItemValues(scope).join("\u0000")],
      () => action(["syncItems"]),
    );
    track(
      () => [getCurrentValue(scope)],
      () => action(["followCurrentPage"]),
    );
  },

  on: {
    "ITEM.FOCUS": { actions: ["setFocusedValue"] },
    "ITEM.BLUR": { actions: ["clearFocus"] },
    "ITEM.CLICK": { actions: ["rememberItem"] },
    "ITEM.NAVIGATE": { actions: ["navigate"] },
    "ITEMS.SYNC": { actions: ["syncItems"] },
    "ITEMS.CURRENT": { actions: ["followCurrentPage"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    actions: {
      setFocusedValue({ context, event, scope }) {
        if (event.type !== "ITEM.FOCUS") return;
        context.set("focusedValue", event.value);
        // APG: Tab may restore the control it left. It does here.
        context.set("tabbableValue", event.value);
        // Read at arrival and held: the modality of *now* flips to pointer after
        // 300ms of mouse movement whether or not the focus moved, and a ring that
        // blinks out under the user's hands was the result.
        context.set("focusSource", getInputModality(scope.getDoc()));
      },

      clearFocus({ context }) {
        context.set("focusedValue", null);
        // `tabbableValue` survives on purpose — it *is* the memory Tab returns to.
        context.set("focusSource", null);
      },

      // A pointer press moves the tab stop and nothing else. The activation
      // belongs to the control that was clicked, which is the whole premise of a
      // toolbar of composed controls.
      rememberItem({ context, event }) {
        if (event.type !== "ITEM.CLICK") return;
        context.set("tabbableValue", event.value);
      },

      navigate({ context, prop, scope, event }) {
        if (event.type !== "ITEM.NAVIGATE") return;
        const items = getItemEls(scope);
        const current = items.findIndex((item) => item.dataset.value === event.value);
        const next = getNextIndex(current, event.action, {
          count: items.length,
          loop: prop("loopFocus"),
          // Natively `disabled` only. An `aria-disabled` control stays reachable —
          // APG's discoverability clause, and the control itself is what refuses
          // the activation (`button`'s `focusableWhenDisabled`).
          isDisabled: (index) => items[index]?.hasAttribute("disabled") === true,
        });
        const target = items[next];
        if (target === undefined || next === current) return;

        focusElement(target);
        context.set("tabbableValue", target.dataset.value ?? "");
      },

      // The bar exposes exactly one tab stop, and it has to be one the browser
      // will actually stop on: parked on a disabled button, the only
      // `tabindex="0"` is skipped and the whole toolbar falls out of the tab
      // order.
      //
      // A bar whose stop has never been settled, or whose stop is gone, opens on the
      // page the user is on when one of its items says so with `aria-current="page"`,
      // and on the first enabled item otherwise.
      //
      // It never steals the focus. An item removed while focused drops the focus
      // on body, which is the browser's answer and an acceptable one here —
      // `getRemovalIndex` belongs to the transient collections (a menu), not to a
      // bar that is part of the page.
      syncItems({ context, scope }) {
        const items = getItemEls(scope);
        const values = getItemValues(scope);
        const isDisabled = (index: number): boolean =>
          items[index]?.hasAttribute("disabled") === true;

        const enabled = (value: string | null): boolean => {
          if (value === null) return false;
          const index = values.indexOf(value);
          return index !== -1 && !isDisabled(index);
        };

        if (enabled(context.get("tabbableValue"))) return;
        const current = getCurrentValue(scope);
        context.set(
          "tabbableValue",
          current ?? values[getInitialIndex({ count: items.length, isDisabled })] ?? null,
        );
      },

      // A route change moves the page the bar is on, and the stop goes with it so
      // that Tab enters on the new page. While the focus is inside the bar the stop
      // is the focused item and stays there; a re-render on the same page never gets
      // here, so the memory of where the user left the bar survives it.
      followCurrentPage({ context, scope }) {
        if (context.get("focusedValue") !== null) return;
        const current = getCurrentValue(scope);
        if (current !== null) context.set("tabbableValue", current);
      },
    },

    effects: {
      // No listener of its own: the source is read once, when focus lands. Holding
      // the handle is the whole job — the tracker has to be running before the
      // first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      /**
       * `role="toolbar"` with no accessible name is what the APG forbids and
       * what no automated check catches: axe has no rule for it, so the defect
       * ships green. Defaulting a name is worse than none — two bars both called
       * "Toolbar" are less navigable than two unnamed ones, because the name is
       * how a screen-reader user tells them apart — so the core says so instead.
       *
       * Read off the mounted element rather than off the props: `label` is only
       * one of the three ways in, and a consumer pointing at a visible heading
       * with their own `aria-labelledby` has done the right thing.
       */
      warnIfAnonymous({ scope }) {
        if (!isDev()) return;
        const root = getRootEl(scope);
        if (root === null) return;
        warn(
          !root.hasAttribute("aria-label") && !root.hasAttribute("aria-labelledby"),
          `a toolbar has no accessible name. Pass \`label\`, or point at a visible \
heading with your own \`aria-labelledby\` — the APG requires the name, and two \
unnamed bars on a page cannot be told apart.`,
        );
      },

      trackItems({ scope, send }) {
        send({ type: "ITEMS.SYNC" });
        // Controls appear and disappear with the app's own state; the tab stop has
        // to survive that without the consumer telling anyone.
        return observeChildren(
          getRootEl(scope),
          (_root, records) => {
            send({ type: "ITEMS.SYNC" });
            const moved = records.some(
              (record) =>
                record.type === "attributes" &&
                record.target.nodeType === 1 &&
                (record.target as Element).matches('[data-part~="toolbar:item"]') &&
                record.oldValue !== (record.target as Element).getAttribute("aria-current"),
            );
            if (moved) send({ type: "ITEMS.CURRENT" });
          },
          ["aria-current"],
        );
      },
    },
  },
});

import type { RovingAction } from "../../focus/roving-focus";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality, Orientation } from "../../types";

export interface ToolbarMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly orientation?: Orientation | undefined;
  /** Whether the arrows wrap at the ends. APG leaves it open; `toggle-group` loops. */
  readonly loopFocus?: boolean | undefined;
  /** The toolbar's accessible name (APG requires one) — rendered as `aria-label`. */
  readonly label?: string | undefined;
}

export interface ResolvedToolbarMachineProps extends ToolbarMachineProps {
  readonly orientation: Orientation;
  readonly loopFocus: boolean;
}

export interface ToolbarItemProps {
  /** The item's identity in the roving order. The adapter defaults it to its own id. */
  readonly value?: string | undefined;
}

export interface ToolbarSeparatorProps {
  /**
   * Rare: force the visual orientation. Defaults to the perpendicular of the
   * toolbar's own axis, which is what a rule between two groups means.
   */
  readonly orientation?: Orientation | undefined;
}

export interface ToolbarTitleProps {
  /** Where the title sits in a navigation bar: in the row of controls, or large under it. */
  readonly size?: "inline" | "large" | undefined;
}

export interface ToolbarSchema extends MachineSchema {
  state: "idle";
  props: ResolvedToolbarMachineProps;
  context: {
    /** The single tab stop, and the memory Tab comes back to. */
    tabbableValue: string | null;
    /** The item that actually holds DOM focus, if any. */
    focusedValue: string | null;
    /** The modality the focus arrived under, held until it leaves. */
    focusSource: InputModality | null;
  };
  event:
    | { type: "ITEM.FOCUS"; value: string }
    | { type: "ITEM.BLUR" }
    | { type: "ITEM.CLICK"; value: string }
    | { type: "ITEM.NAVIGATE"; action: RovingAction; value: string }
    | { type: "ITEMS.SYNC" }
    | { type: "ITEMS.CURRENT" };
  action:
    | "setFocusedValue"
    | "clearFocus"
    | "rememberItem"
    | "navigate"
    | "syncItems"
    | "followCurrentPage";
  effect: "trackModality" | "trackItems" | "warnIfAnonymous";
}

export interface ToolbarApi<T extends PropTypes = PropTypes> {
  readonly focusedValue: string | null;
  getRootProps(): T["element"];
  getGroupProps(): T["element"];
  getSeparatorProps(props?: ToolbarSeparatorProps): T["element"];
  getSpacerProps(): T["element"];
  getItemProps(props: ToolbarItemProps & { value: string }): T["element"];
  getTitleProps(props?: ToolbarTitleProps): T["element"];
}

/**
 * `<Toolbar items={…}/>` — one loop over five entry shapes, narrowed
 * structurally: `"separator" in entry`, `"spacer" in entry`, `"options" in entry`,
 * a title when there is no `value`, and an action otherwise. The title is told from
 * an action by the one field an action cannot be without, never by `title`, which is
 * also an HTML attribute a consumer may well write on a stop. No `kind` field, the
 * same rule `menu` and `select` already follow.
 *
 * **`value` is required on an action**, where the part defaults it. `ToolbarItem`
 * falls back to a `useId` when given none, which is right for a bar written by
 * hand — a stop still needs an identity and inventing one is better than
 * refusing. It is wrong here for two reasons at once: the identity would be
 * allocated fresh on a render that reorders the array, and this layer also needs a
 * React key, which cannot come from `label` because `label` is a `ReactNode`. One
 * required string answers both, and the second is the one that would have been
 * discovered late.
 *
 * **A group is `aria-label`, not a label part**, and this is the one place
 * `ComposedGroup`'s contract does not transfer. Elsewhere the group's own `label`
 * prop is a *boolean* pointing an `aria-labelledby` at a label part the layer must
 * render — `SelectItemGroup`, `MenuItemGroup`. `ToolbarGroup` has no such part and
 * no such prop: it is a plain cluster whose name is an attribute. So the shape is
 * borrowed for its fields and its `id` still pins the key, but the label lands on
 * the group itself.
 *
 * **`render` per entry rather than one `renderItem` for the bar.** A toolbar's
 * stops are heterogeneous by nature — the documentation site's own bar composes
 * three `ToggleRoot`s, two `ButtonRoot`s and a share button in a single row — so
 * the substitution belongs to the entry, exactly as `ComposedTrigger` puts it on
 * the trigger. A single `render*` for the whole bar would have to switch on the
 * entry to give the same result, which is the loop this file already is.
 */

import type { ReactElement, ReactNode } from "react";
import type { ComposedDecoration, ComposedGroup, ComposedSeparator } from "../../composed";
import type { PartProps } from "../../create-part";
import {
  ToolbarGroup,
  ToolbarItem,
  ToolbarRoot,
  ToolbarSeparator,
  ToolbarSpacer,
  ToolbarTitle,
  type UseToolbarProps,
} from "./toolbar";

/** One stop of the roving order. */
export interface ToolbarAction<Meta = never> extends ComposedDecoration<Meta> {
  /** The stop's identity, and this layer's key. Required — see above. */
  readonly value: string;
  readonly label: ReactNode;
  /**
   * The control this stop *is*, handed to the part's `render` — never wrapped by
   * it. `ToolbarItem` is the focusable itself, so a control nested inside one
   * would leave the bar roving over an element the browser cannot focus.
   */
  readonly render?: ReactElement | undefined;
  readonly disabled?: boolean | undefined;
  /** Refused: `title` is the key of the title entry, never an attribute of a stop. */
  readonly title?: never;
}

/** What pushes everything after it to the far edge. */
export interface ToolbarSpacerEntry {
  readonly spacer: true;
}

/** The title of a navigation bar, in the row of controls or large under it. */
export interface ToolbarTitleEntry {
  readonly title: ReactNode;
  readonly size?: "inline" | "large" | undefined;
  readonly label?: never;
}

export type ToolbarEntry<Meta = never> =
  | ToolbarAction<Meta>
  | ComposedSeparator
  | ToolbarSpacerEntry
  | ToolbarTitleEntry
  | ComposedGroup<ToolbarAction<Meta>>;

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it.
 */
export interface ToolbarParts {
  readonly group?: Omit<PartProps<"div">, "id" | "ref" | "aria-label"> | undefined;
  readonly separator?: Omit<PartProps<"div">, "id" | "ref"> | undefined;
  readonly spacer?: Omit<PartProps<"div">, "id" | "ref"> | undefined;
  readonly title?: Omit<PartProps<"h1">, "id" | "ref"> | undefined;
  /**
   * Applied to EVERY stop, hence no `value` — the entry's own field — and no `id`
   * **or IDREF**: one id repeated down a bar is a broken reference per stop, and
   * one `aria-labelledby` repeated gives every stop the same name, which no
   * dangling-IDREF check can see because the id it points at does resolve. `ref`
   * goes because a single ref held by N stops ends up holding the last one, and
   * `render` because the substitution is the entry's.
   */
  readonly item?:
    | Omit<
        PartProps<"button">,
        "id" | "ref" | "render" | "value" | "aria-labelledby" | "aria-describedby"
      >
    | undefined;
}

export interface ToolbarComposedProps<Meta = never>
  extends UseToolbarProps,
    Omit<PartProps<"div", UseToolbarProps>, "children"> {
  readonly items: readonly ToolbarEntry<Meta>[];
  readonly parts?: ToolbarParts | undefined;
}

export function Toolbar<Meta = never>(props: ToolbarComposedProps<Meta>): ReactNode {
  const { items, parts, ...root } = props;

  const stop = (action: ToolbarAction<Meta>): ReactNode => (
    <ToolbarItem
      key={action.value}
      value={action.value}
      disabled={action.disabled}
      render={action.render}
      {...parts?.item}
    >
      {action.icon}
      {action.label}
    </ToolbarItem>
  );

  // Extracted rather than written inline, and keyed on the position, exactly as
  // `menu/composed.tsx` keys its own separators: neither a rule nor a spacer is
  // focusable, holds state or has a subtree to unmount, so a position key costs
  // nothing here where one on a stop would move the focus mid-interaction — the
  // collection being the live DOM the machine reads.
  const renderEntry = (entry: ToolbarEntry<Meta>, index: number): ReactNode => {
    if ("separator" in entry) {
      return <ToolbarSeparator key={`rule:${index}`} {...parts?.separator} />;
    }
    if ("spacer" in entry) {
      return <ToolbarSpacer key={`gap:${index}`} {...parts?.spacer} />;
    }
    if ("options" in entry) {
      return (
        <ToolbarGroup key={entry.id} aria-label={entry.label} {...parts?.group}>
          {entry.options.map(stop)}
        </ToolbarGroup>
      );
    }
    if (!("value" in entry)) {
      return (
        <ToolbarTitle key={`title:${index}`} size={entry.size} {...parts?.title}>
          {entry.title}
        </ToolbarTitle>
      );
    }
    return stop(entry);
  };

  return <ToolbarRoot {...root}>{items.map(renderEntry)}</ToolbarRoot>;
}

/**
 * The toolbar in React. Five parts, one machine, and one decision that is the
 * adapter's alone.
 *
 * **`type="button"` is placed here and never by `connect`.** An item is whatever
 * the author composed into it — a `<button>`, an anchor, a `Toggle.Root` — and a
 * `type` attribute posted by the machine would land on an `<a>` that has no such
 * thing. So the wrapper adds it to *its own* default element and stops there,
 * which also leaves `type="submit"` available to a consumer who means it.
 *
 * The item's `value` defaults to a `useId()`: identity in the roving order is
 * what the machine needs, not a name the author has to invent, and a bar of icon
 * buttons rarely has one to give.
 */

import * as toolbar from "@standarui/core/toolbar";
import { type ReactNode, useId } from "react";
import { createPart, type PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type ToolbarApi = toolbar.ToolbarApi<ReactPropTypes>;

const ToolbarContext = createPartContext<ToolbarApi>("Toolbar");

export interface UseToolbarProps extends toolbar.ToolbarMachineProps, MachineRuntimeProps {}

export function useToolbar(props: UseToolbarProps): ToolbarApi {
  return toolbar.connect(useMachine(toolbar.machine, props), normalizeProps);
}

/** The api of the bar a subtree sits in — a consumer's own chrome reads it. */
export function useToolbarContext(): ToolbarApi {
  return ToolbarContext.usePart("ToolbarContext");
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "orientation",
  "loopFocus",
  "label",
] as const;

export interface ToolbarRootProps extends UseToolbarProps, PartProps<"div", UseToolbarProps> {}

export function ToolbarRoot(props: ToolbarRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useToolbar(machineProps);

  return (
    <ToolbarContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </ToolbarContext.Provider>
  );
}

/**
 * A cluster of related controls — the leading and trailing groups of a title bar.
 * It changes nothing about the roving: its children are items like any others,
 * which is exactly why a group of toggles belongs here rather than in a
 * `toggle-group` (two rovings on one axis fight over `preventDefault`).
 */
export const ToolbarGroup: (props: PartProps<"div">) => ReactNode = createPart(ToolbarContext, {
  name: "ToolbarGroup",
  element: "div",
  props: (api) => api.getGroupProps(),
});

/** The toolbar's `Spacer`: what pushes the trailing group to the far edge. */
export const ToolbarSpacer: (props: PartProps<"div">) => ReactNode = createPart(ToolbarContext, {
  name: "ToolbarSpacer",
  element: "div",
  props: (api) => api.getSpacerProps(),
});

export interface ToolbarSeparatorProps
  extends toolbar.ToolbarSeparatorProps,
    PartProps<"div", toolbar.ToolbarSeparatorProps> {}

/**
 * A part of the toolbar rather than a composed `Separator`: the rule between two
 * groups is as tall as an icon and runs across the bar, where a standalone
 * separator stretches. Both sheets would be at specificity zero in the same
 * layer, so only source order would decide — four duplicated declarations against
 * a cascade accident.
 */
export function ToolbarSeparator(props: ToolbarSeparatorProps): ReactNode {
  const [separatorProps, rest] = splitProps(props, ["orientation"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = ToolbarContext.usePart("ToolbarSeparator");

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getSeparatorProps(separatorProps),
    elementProps,
    children,
  });
}

export interface ToolbarTitleProps
  extends toolbar.ToolbarTitleProps,
    PartProps<"h1", toolbar.ToolbarTitleProps> {}

/**
 * The title of a navigation bar — anatomy only, no state and no roving stop. It
 * renders an `h1` and the consumer picks the level that fits the page with `render`.
 */
export function ToolbarTitle(props: ToolbarTitleProps): ReactNode {
  const [titleProps, rest] = splitProps(props, ["size"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = ToolbarContext.usePart("ToolbarTitle");

  return useRender({
    render,
    asChild,
    element: "h1",
    props: api.getTitleProps(titleProps),
    elementProps,
    children,
  });
}

export interface ToolbarItemProps
  extends toolbar.ToolbarItemProps,
    PartProps<"button", toolbar.ToolbarItemProps> {}

/**
 * One stop of the roving order. It is the focusable itself — compose a control
 * into it with `render`, never wrap one in it, or the bar would rove over
 * elements the browser cannot focus.
 */
export function ToolbarItem(props: ToolbarItemProps): ReactNode {
  const [itemProps, rest] = splitProps(props, ["value"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = ToolbarContext.usePart("ToolbarItem");
  const fallback = useId();

  // Only on the element this part renders itself. A composed `<a>` or a
  // `Toggle.Root` brings its own element and its own attributes; the consumer's
  // own `type` still wins, because their props are spread last.
  const substituted = render !== undefined || asChild === true;
  const ownProps = substituted ? elementProps : { type: "button" as const, ...elementProps };

  return useRender({
    render,
    asChild,
    element: "button",
    props: api.getItemProps({ value: itemProps.value ?? fallback }),
    elementProps: ownProps,
    children,
  });
}
